import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to mimic specific ELA features.
    This function combines a rotated elliptic function, a multimodal cosine mixture, and a skewed component based on the arctangent.

    Formula:
    f(x) = 0.1*elliptic_rotated(x) + 0.05*cosine_mixture(x) + 0.01*skewed_arctan(x)

    Components:
    - Rotated Elliptic: elliptic_rotated(x) creates an ill-conditioned quadratic form with dependencies between dimensions. The values are scaled.
    - Cosine Mixture: cosine_mixture(x) introduces multimodality and local optima to make the problem more complex. The values are scaled.
    - Skewed Arctangent: skewed_arctan(x) adds skewness to the function landscape.  The values are scaled.
    """

    def elliptic_rotated(x: np.ndarray) -> float:
        """Rotated elliptic function."""
        D = len(x)
        rotated_x = x @ np.array([[np.cos(np.pi / 6), -np.sin(np.pi / 6)], [np.sin(np.pi / 6), np.cos(np.pi / 6)]]) if D==2 else x
        return np.sum((10**(i / (D - 1))) * rotated_x**2 for i, rotated_x in enumerate(rotated_x))

    def cosine_mixture(x: np.ndarray) -> float:
        """Cosine mixture function."""
        return np.sum(np.cos(5 * x) - 0.5*x for x in x)

    def skewed_arctan(x: np.ndarray) -> float:
        """Skewed arctangent function."""
        return np.sum(np.arctan(x + 2) * np.exp(-x/3) for x in x)

    return 0.1*elliptic_rotated(x) + 0.05*cosine_mixture(x) + 0.01*skewed_arctan(x)
